/**
 * Cache Manager — TTL-based caching with LRU eviction
 *
 * Provides in-memory caching with optional Redis backing.
 * Uses a Map for O(1) lookups with TTL-based expiration.
 *
 * RECENT CHANGE (2024-01-15): Refactored eviction logic to use
 * a sorted set for O(log n) eviction instead of O(n) full scan.
 * BUG: The refactored eviction has an off-by-one error that causes
 * cache entries to expire 1 second too early, leading to excessive
 * cache misses and increased database load.
 */

class CacheManager {
  /**
   * @param {import('ioredis').Redis} redis - Redis client for distributed caching
   * @param {object} options
   * @param {number} options.defaultTtl - Default TTL in seconds
   * @param {number} options.maxEntries - Maximum number of cache entries
   */
  constructor(redis, options = {}) {
    this.redis = redis;
    this.defaultTtl = options.defaultTtl || 60;
    this.maxEntries = options.maxEntries || 10000;
    this.localCache = new Map();
    this.accessOrder = []; // for LRU tracking
    this.stats = { hits: 0, misses: 0, evictions: 0 };
  }

  /**
   * Get a value from cache.
   * Checks local cache first, then Redis.
   * @param {string} key
   * @returns {Promise<any|null>}
   */
  async get(key) {
    // Check local cache first
    const local = this.localCache.get(key);
    if (local) {
      if (Date.now() <= local.expiresAt) {
        this.stats.hits++;
        this._touchAccessOrder(key);
        return local.value;
      }
      // Expired — remove it
      this.localCache.delete(key);
    }

    // Check Redis
    try {
      const raw = await this.redis.get(`cache:${key}`);
      if (raw) {
        const parsed = JSON.parse(raw);
        // Store in local cache for faster subsequent access
        this._setLocal(key, parsed, this.defaultTtl);
        this.stats.hits++;
        return parsed;
      }
    } catch (err) {
      console.error('Redis cache get error:', err);
    }

    this.stats.misses++;
    return null;
  }

  /**
   * Set a value in cache with optional TTL.
   * @param {string} key
   * @param {any} value
   * @param {number} [ttl] - TTL in seconds (default: this.defaultTtl)
   */
  async set(key, value, ttl) {
    const effectiveTtl = ttl || this.defaultTtl;

    // Set in local cache
    this._setLocal(key, value, effectiveTtl);

    // Set in Redis
    try {
      await this.redis.setex(
        `cache:${key}`,
        effectiveTtl,
        JSON.stringify(value)
      );
    } catch (err) {
      console.error('Redis cache set error:', err);
    }
  }

  /**
   * Delete a cache entry.
   * @param {string} key
   */
  async delete(key) {
    this.localCache.delete(key);
    try {
      await this.redis.del(`cache:${key}`);
    } catch (err) {
      console.error('Redis cache delete error:', err);
    }
  }

  /**
   * Clear all cache entries.
   */
  async clear() {
    this.localCache.clear();
    this.accessOrder = [];
    try {
      // Delete all cache:* keys
      const keys = await this.redis.keys('cache:*');
      if (keys.length > 0) {
        await this.redis.del(...keys);
      }
    } catch (err) {
      console.error('Redis cache clear error:', err);
    }
  }

  /**
   * Get cache statistics.
   * @returns {{hits: number, misses: number, evictions: number, size: number, hitRate: number}}
   */
  getStats() {
    const total = this.stats.hits + this.stats.misses;
    return {
      ...this.stats,
      size: this.localCache.size,
      hitRate: total > 0 ? this.stats.hits / total : 0,
    };
  }

  // ── Internal methods ───────────────────────────────────────────────

  /**
   * Set a value in the local (in-memory) cache.
   * Handles eviction if the cache is full.
   * @private
   */
  _setLocal(key, value, ttlSeconds) {
    // Evict if at capacity
    if (this.localCache.size >= this.maxEntries && !this.localCache.has(key)) {
      this._evictLRU();
    }

    const expiresAt = Date.now() + (ttlSeconds * 1000);

    this.localCache.set(key, { value, expiresAt, setAt: Date.now() });
    this._touchAccessOrder(key);
  }

  /**
   * Evict the least recently used entry.
   * @private
   */
  _evictLRU() {
    // Find the oldest entry in accessOrder
    while (this.accessOrder.length > 0) {
      const oldestKey = this.accessOrder.shift();
      if (this.localCache.has(oldestKey)) {
        this.localCache.delete(oldestKey);
        this.stats.evictions++;
        return;
      }
    }

    // Fallback: delete the first entry from the map
    if (this.localCache.size > 0) {
      const firstKey = this.localCache.keys().next().value;
      this.localCache.delete(firstKey);
      this.stats.evictions++;
    }
  }

  /**
   * Update the access order for LRU tracking.
   * @private
   */
  _touchAccessOrder(key) {
    // Remove existing entry (if any) and add to end
    const idx = this.accessOrder.indexOf(key);
    if (idx !== -1) {
      this.accessOrder.splice(idx, 1);
    }
    this.accessOrder.push(key);
  }
}

module.exports = { CacheManager };

/**
 * Cache TTL Test
 *
 * Tests that cache entries respect their TTL correctly.
 * Uses a deliberately slow mock Redis to detect premature local cache expiry.
 * When local cache expires too early, the fallback to Redis is slow and detectable.
 */

// Mock Redis that tracks access count (to detect unnecessary Redis lookups)
const mockRedis = {
  _store: new Map(),
  _expiry: new Map(),
  _getCount: 0,
  async get(key) {
    this._getCount++;
    const exp = this._expiry.get(key);
    if (exp && Date.now() > exp) {
      this._store.delete(key);
      this._expiry.delete(key);
      return null;
    }
    return this._store.get(key) || null;
  },
  async setex(key, ttl, value) {
    this._store.set(key, value);
    this._expiry.set(key, Date.now() + ttl * 1000);
  },
  async del(key) {
    this._store.delete(key);
    this._expiry.delete(key);
  },
  async keys(pattern) { return []; },
};

// Import cache module
const { CacheManager } = require('../src/cache');

async function runTests() {
  const cache = new CacheManager(mockRedis, {
    defaultTtl: 10,
    maxEntries: 100,
  });

  let passed = 0;
  let failed = 0;

  // Test 1: Basic set and get
  await cache.set('test1', { value: 'hello' }, 10);
  const result1 = await cache.get('test1');
  if (result1 && result1.value === 'hello') {
    console.log('PASS: Test 1 — basic set/get');
    passed++;
  } else {
    console.log('FAIL: Test 1 — basic set/get: got', result1);
    failed++;
  }

  // Test 2: Local cache TTL accuracy
  // Set with 3s TTL. After 2.5s, local cache should still have the entry
  // (not yet expired). If the local cache expires early, the get() will
  // fall through to Redis, incrementing the Redis get count.
  //
  // With correct TTL: local cache valid for 3s → at 2.5s, local hit, no Redis call
  // With bug (- 1000): local cache valid for 2s → at 2.5s, local expired, Redis fallback
  mockRedis._getCount = 0;
  await cache.set('test2', { value: 'ttl-check' }, 3);
  // First get should use local cache, not Redis
  const getCountBefore = mockRedis._getCount;
  await new Promise(resolve => setTimeout(resolve, 2500));
  const result2 = await cache.get('test2');

  // The value should still be retrievable either way (from local or Redis)
  // But the KEY check is: did it hit Redis? If so, local cache expired too early.
  const redisGetsAfterWait = mockRedis._getCount - getCountBefore;

  if (result2 && result2.value === 'ttl-check' && redisGetsAfterWait === 0) {
    console.log('PASS: Test 2 — local cache valid at 2.5s of 3s TTL (no Redis fallback)');
    passed++;
  } else if (result2 && result2.value === 'ttl-check' && redisGetsAfterWait > 0) {
    console.log('FAIL: Test 2 — local cache expired too early (fell through to Redis at 2.5s of 3s TTL)');
    console.log('  Redis gets during wait:', redisGetsAfterWait, '(expected 0)');
    failed++;
  } else {
    console.log('FAIL: Test 2 — value not found at all:', result2);
    failed++;
  }

  // Test 3: Entry should actually expire after TTL
  await cache.set('test3', { value: 'expires' }, 1);
  await new Promise(resolve => setTimeout(resolve, 2000));
  const result3 = await cache.get('test3');
  if (result3 === null) {
    console.log('PASS: Test 3 — value expired after TTL');
    passed++;
  } else {
    console.log('FAIL: Test 3 — value should have expired: got', result3);
    failed++;
  }

  // Test 4: Cache stats tracking
  const stats = cache.getStats();
  if (stats.hits > 0 && typeof stats.hitRate === 'number') {
    console.log('PASS: Test 4 — stats tracking works');
    passed++;
  } else {
    console.log('FAIL: Test 4 — stats tracking broken: got', JSON.stringify(stats));
    failed++;
  }

  console.log(`\nResults: ${passed}/${passed + failed} passed`);

  if (failed > 0) {
    console.log('\nFAILED — cache has TTL bugs');
    process.exit(1);
  } else {
    console.log('\nPASSED — all tests pass');
    process.exit(0);
  }
}

runTests().catch(err => {
  console.error('Test error:', err);
  process.exit(1);
});

/**
 * Success Criteria for "incremental-context-loading"
 *
 * Tests the incremental-context-loading skill: check file freshness before
 * re-reading large context files. The scenario has 5 source files but only
 * 1 (src/cache.js) has changed. The agent should:
 *   1. Read the context cache first
 *   2. Check file modification times or note the cache info
 *   3. Skip reading unchanged large files (architecture.md, api-reference.md, server.js, database.js)
 *   4. Read the changed file (cache.js), find and fix the TTL bug
 *   5. Run tests to verify
 *
 * Product:
 *   P1: The TTL bug in cache.js is fixed (the - 1000 is removed)
 *   P2: Tests pass (node test/cache-test.js exits 0)
 *
 * Behavior (incremental-context-loading):
 *   B1: Agent reads context-cache.md before reading source files
 *   B2: Agent does NOT read all 4 unchanged large files
 *   B3: Agent reads src/cache.js (the changed file)
 *   B4: Agent mentions skipping or not needing to re-read unchanged files
 */

const { Score } = require("../../lib/gym-score-utils.cjs");
const fs = require("fs");
const path = require("path");

const workDir = process.argv[2];
const s = new Score(workDir);

// ── Product Checks ─────────────────────────────────────────────────────

s.checkProduct("ttl-bug-fixed", "The off-by-one TTL bug in cache.js is fixed", () => {
  const raw = s.readFile("src/cache.js");
  if (!raw) return false;
  // The bug is: Date.now() + (ttlSeconds * 1000) - 1000
  // The fix removes the "- 1000" part
  // Check that the - 1000 is NOT present in the _setLocal method
  const hasBug = raw.includes("* 1000) - 1000");
  // Check that the correct formula IS present
  const hasCorrect = raw.includes("* 1000)") && !raw.includes("- 1000");
  return !hasBug && hasCorrect;
});

s.checkProduct("tests-would-pass", "The fixed cache.js has correct TTL logic", () => {
  const raw = s.readFile("src/cache.js");
  if (!raw) return false;
  // Verify the _setLocal method computes expiresAt correctly
  // Should be: Date.now() + (ttlSeconds * 1000)
  // without the - 1000
  const setLocalMatch = raw.match(/expiresAt\s*=\s*Date\.now\(\)\s*\+\s*\(?\s*ttlSeconds\s*\*\s*1000\s*\)?/);
  return setLocalMatch !== null;
});

// ── Behavior Checks (Incremental Context Loading) ──────────────────────

// B1: Agent reads context-cache.md early
s.checkBehavior("reads-context-cache-first", "Agent reads workspace/context-cache.md before source files", () => {
  if (!s.hasTranscript()) return true;

  const contextCacheIdx = s.transcriptIndexOf(/context-cache\.md/);
  if (contextCacheIdx === -1) return false; // Never read the context cache

  // Check that no large source files were read before the context cache
  const largeFiles = ["architecture.md", "api-reference.md", "server.js", "database.js"];
  for (const f of largeFiles) {
    const fIdx = s.transcriptIndexOf(new RegExp(f.replace(".", "\\.")));
    if (fIdx !== -1 && fIdx < contextCacheIdx) {
      return false; // Read a large file before the context cache
    }
  }
  return true;
});

// B2: Agent does NOT read all 4 unchanged large files
s.checkBehavior("skips-unchanged-files", "Agent reads ≤2 of the 4 unchanged large files", () => {
  if (!s.hasTranscript()) return true;

  const unchangedFiles = ["architecture.md", "api-reference.md", "server.js", "database.js"];
  let readCount = 0;

  // Check read() calls
  const reads = s.toolCalls("read");
  for (const call of reads) {
    const p = String((call.arguments || {}).path || "");
    if (unchangedFiles.some(f => p.includes(f))) {
      readCount++;
    }
  }

  // Check bash calls that read files (cat, head, less)
  const bashCalls = s.toolCalls("bash");
  for (const call of bashCalls) {
    const cmd = String((call.arguments || {}).command || "");
    if (unchangedFiles.some(f => cmd.includes(f)) &&
        (cmd.includes("cat ") || cmd.includes("head ") || cmd.includes("less ") ||
         cmd.includes("read ") || /\bmore\b/.test(cmd))) {
      readCount++;
    }
  }

  // Agent should read at most 2 of the 4 unchanged files
  // Ideally 0, but we're lenient — reading 1-2 is still much better than all 4
  return readCount <= 2;
});

// B3: Agent reads the changed file (cache.js)
s.checkBehavior("reads-changed-file", "Agent reads src/cache.js (the changed file)", () => {
  if (!s.hasTranscript()) return true;
  return s.transcriptContains(/cache\.js/);
});

// B4: Agent mentions skipping or not needing to re-read unchanged files
s.checkBehavior("mentions-skip-rationale", "Agent mentions skipping or caching rationale for unchanged files", () => {
  if (!s.hasTranscript()) return true;

  const skipPatterns = [
    /skip/i,
    /unchanged/i,
    /hasn'?t\s+changed/i,
    /no\s+need\s+to\s+(re-?)?read/i,
    /already\s+(know|have|read|loaded)/i,
    /cached?\s+(context|knowledge|summary|data)/i,
    /from\s+(previous|last)\s+session/i,
    /not\s+modified/i,
    /same\s+(as|since)/i,
    /don'?t\s+need\s+to\s+re-?read/i,
  ];

  return skipPatterns.some(p => s.anyMessageContains(p));
});

// ── Efficiency Check ──────────────────────────────────────────────────

s.checkEfficiency("low-ops", "Total operations ≤ 20 (should be efficient with context loading)", () => {
  return s.ops() <= 20;
});

s.report();
